<?php $title='Pré-check-in '.$portal['code'];require BASE_PATH.'/app/Views/public/_top.php';$guests=$precheckin['guests'];for($i=count($guests);$i<10;$i++)$guests[]=[];?>
<section class="reservation-card"><p class="eyebrow">Pré-check-in</p><h1>Prepare sua chegada</h1><p>Status: <strong><?= e($precheckin['status']) ?></strong>. Cadastre no máximo 10 hóspedes, incluindo crianças.</p><?php if($message=flash('success')):?><div class="alert alert-success"><?= e($message) ?></div><?php endif;?><?php if($message=flash('error')):?><div class="alert alert-error"><?= e($message) ?></div><?php endif;?></section>
<form class="reservation-card admin-form" method="post" action="<?= e(base_url('minha-reserva/'.rawurlencode($token).'/pre-checkin')) ?>"><?= csrf_field() ?><h2>Responsável</h2><label>Nome completo<input name="responsible_name" value="<?= e($precheckin['responsible_name']) ?>" required></label><label>CPF<input name="responsible_cpf" value="<?= e($precheckin['responsible_cpf']) ?>" required></label><label>Nascimento<input type="date" name="responsible_birth_date" value="<?= e($precheckin['responsible_birth_date']) ?>"></label><label>Documento complementar<input name="responsible_document" value="<?= e($precheckin['responsible_document']) ?>"></label><label>Horário estimado<input type="time" name="estimated_arrival_time" value="<?= e($precheckin['estimated_arrival_time']) ?>"></label>
<h2>Hóspedes</h2><?php foreach($guests as $i=>$guest):?><fieldset><legend>Hóspede <?= $i+1 ?></legend><label>Nome completo<input name="guests[<?= $i ?>][full_name]" value="<?= e($guest['full_name']??'') ?>" <?= $i===0?'required':'' ?>></label><label>CPF<input name="guests[<?= $i ?>][cpf]" value="<?= e($guest['cpf']??'') ?>"></label><label>Documento<input name="guests[<?= $i ?>][document_number]" value="<?= e($guest['document_number']??'') ?>"></label><label>Nascimento<input type="date" name="guests[<?= $i ?>][birth_date]" value="<?= e($guest['birth_date']??'') ?>"></label><label><input type="checkbox" name="guests[<?= $i ?>][is_responsible]" value="1" <?= !empty($guest['is_responsible'])?'checked':'' ?>> Responsável</label></fieldset><?php endforeach;?>
<h2>Veículos</h2><?php for($i=0;$i<3;$i++):$vehicle=$precheckin['vehicles'][$i]??[];?><fieldset><label>Placa<input name="vehicles[<?= $i ?>][plate]" value="<?= e($vehicle['plate']??'') ?>"></label><label>Marca/modelo<input name="vehicles[<?= $i ?>][make_model]" value="<?= e($vehicle['make_model']??'') ?>"></label><label>Cor<input name="vehicles[<?= $i ?>][color]" value="<?= e($vehicle['color']??'') ?>"></label><label>Condutor<input name="vehicles[<?= $i ?>][driver_name]" value="<?= e($vehicle['driver_name']??'') ?>"></label></fieldset><?php endfor;?>
<h2>Aceite específico das regras</h2><?php foreach(\Refugio\Services\PreCheckinService::REQUIRED_RULES as $rule):?><label><input type="checkbox" name="rules[<?= e($rule) ?>]" value="1"> Confirmo a regra: <?= e($rule) ?></label><?php endforeach;?><label>Observações<textarea name="notes"><?= e($precheckin['notes']) ?></textarea></label><div class="form-actions"><button class="secondary-button" name="intent" value="save">Salvar rascunho</button><button class="primary-button" name="intent" value="submit">Enviar para análise</button></div></form>
